def subtract(a, b):
    # Normalize and filter out empty intervals
    a_intervals = [interval for interval in a if interval[0] < interval[1]]
    b_intervals = [interval for interval in b if interval[0] < interval[1]]

    if not a_intervals:
        return []

    # Merge overlapping intervals in a
    a_intervals.sort()
    merged_a = []
    for start, end in a_intervals:
        if merged_a and merged_a[-1][1] >= start:
            merged_a[-1][1] = max(merged_a[-1][1], end)
        else:
            merged_a.append([start, end])

    # Merge overlapping intervals in b
    b_intervals.sort()
    merged_b = []
    for start, end in b_intervals:
        if merged_b and merged_b[-1][1] >= start:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in merged_a:
        current = a_start
        for b_start, b_end in merged_b:
            if b_end <= current or b_start >= a_end:
                # No overlap
                continue
            if b_start > current:
                # Add the part before b starts
                result.append([current, b_start])
            current = max(current, b_end)
        if current < a_end:
            # Add the remaining part
            result.append([current, a_end])

    return result

